void BitVec_set(BitVec* bvec, u64 i)
{
    u64 byte_index = i / 8;
    u64 bit_index  = i % 8;

    while (wc_unlikely(byte_index >= bvec->arr.size)) {
        u8 zero = 0;
        GenVec_push(&bvec->arr, &zero);
    }

    u8* byte = GenVec_get_ptr_mut(&bvec->arr, byte_index);
    *byte |= (u8)(1u << bit_index);

    if (i + 1 > bvec->size) {
        bvec->size = i + 1;
    }
}

// Clear bit i (set to 0)
void BitVec_clear(BitVec* bvec, u64 i)
{
    WC_ASSERT(i < bvec->size, "index out of bounds");

    u64 byte_index = i / 8;
    u64 bit_index  = i % 8;

    u8* byte = GenVec_get_ptr_mut(&bvec->arr, byte_index);
    *byte &= (u8) ~(1u << bit_index);
}

// Test bit i (returns 1 or 0)
u8 BitVec_test(const BitVec* bvec, u64 i)
{
    WC_ASSERT(i < bvec->size, "index out of bounds");

    u64 byte_index = i / 8;
    u64 bit_index  = i % 8;

    return (*(const u8*)GenVec_get_ptr(&bvec->arr, byte_index) >> bit_index) & 1;
}

