{
    WC_ASSERT(i < bvec->size, "index out of bounds");

    u64 byte_index = i / 8;
    u64 bit_index  = i % 8;

    u8* byte = GenVec_get_ptr_mut(&bvec->arr, byte_index);
    *byte ^= (u8)(1u << bit_index);
}


void BitVec_push(BitVec* bvec)
{
    BitVec_set(bvec, bvec->size);
}


